/* The Discover book — topic 1.3 (Investigate the Real Problem) */
export const chapter3: BookChapter = {
  id: "day-3", n: "3", day: 3, title: "Investigate the Real Problem", kicker: "Technical Problem Review",
  question: "What actually goes wrong, how much, and why?",
  intro: [
    { t: "p", text: "Until now the problem has been something people describe. In this topic it becomes something you’ve seen. You reproduce today’s flow on safe data, measure how bad it really is, dig past the symptoms to the causes, and write one problem statement where every claim points at evidence." },
    { t: "p", text: "Topic 1.2 gave you a frame: the problem without solution words, the unknowns ranked as hypotheses, the quality targets and a spike plan. That frame is a set of careful guesses. This topic is where the guesses meet the system. By its end you should be able to say what fails, where, how often, how badly and why — and to point at the evidence for each part of that sentence." },
    { t: "figure", fig: { kind: "anatomy", parts: [{ text: "By the end of this topic you should be able to say " }, { text: "what fails", label: "What", note: "Seen in the trace" }, { text: ", " }, { text: "where", label: "Where", note: "The trace step where it goes wrong" }, { text: ", " }, { text: "how often", label: "How often", note: "From the baseline" }, { text: ", " }, { text: "how badly", label: "How badly", note: "From the baseline" }, { text: " and " }, { text: "why", label: "Why", note: "From the root causes" }, { text: " — and point at the evidence for each part." }] }, caption: "The sentence this topic has to earn. Each part is a claim, and each claim needs its own evidence by the end of the topic." },
    { t: "p", text: "The four lessons are a chain. Each one produces the input the next one needs, so the order matters and skipping one weakens everything after it." },
    { t: "table", caption: "Topic 1.3 at a glance", head: ["Lesson", "The question", "What it produces", "Timebox"], rows: [
      ["1.3.1 Reproduce & Trace", "Where exactly does it go wrong?", "Current flow trace — every step with system, data, time and manual work", "½–1 day"],
      ["1.3.2 Measure the Baseline", "How bad is it, really?", "Baseline measurements — method, sample, median, p95 and source per metric", "½–1 day"],
      ["1.3.3 Find the Root Causes", "What actually causes it?", "Technical root-cause analysis — symptoms, why-chains, causes and evidence", "½ day"],
      ["1.3.4 Write the Statement", "Is this the problem we’ll solve?", "Technical problem statement (TPS) — every clause traced", "2–4 hours"],
    ] },
    { t: "p", text: "The trace tells you where to measure. The baseline tells you which symptoms are big enough to chase. The causes explain the numbers. And the statement gathers all three into a single yardstick that every option in topic 1.4, and the decision in topic 1.5, will be judged against." },
    { t: "figure", fig: { kind: "flow", steps: [{ label: "Trace", sub: "where to measure", tone: "human" }, { label: "Baseline", sub: "which symptoms are big enough", tone: "system" }, { label: "Causes", sub: "explain the numbers", tone: "system" }, { label: "Statement", sub: "yardstick for topics 1.4 and 1.5", tone: "new" }] }, caption: "The four lessons as a chain: each produces what the next one needs, so skipping one weakens everything after it." },
    { t: "p", text: "The topic closes at the **Technical Problem Review**: the trace is repeatable, the baseline has a method and a sample, every cause is evidenced, and every clause of the statement is traced. If any of those four is missing, the review sends you back to the lesson that owns it — not forward to solutions." },
    { t: "figure", fig: { kind: "decide", start: "q1", nodes: [{ id: "q1", q: "Is the trace repeatable?", yes: "q2", no: "r1" }, { id: "q2", q: "Does the baseline have a method and a sample?", yes: "q3", no: "r2" }, { id: "q3", q: "Is every cause evidenced?", yes: "q4", no: "r3" }, { id: "q4", q: "Is every clause of the statement traced?", yes: "ok", no: "r4" }, { id: "r1", result: "Back to 1.3.1 Reproduce & Trace", tone: "bad" }, { id: "r2", result: "Back to 1.3.2 Measure the Baseline", tone: "bad" }, { id: "r3", result: "Back to 1.3.3 Find the Root Causes", tone: "bad" }, { id: "r4", result: "Back to 1.3.4 Write the Statement", tone: "bad" }, { id: "ok", result: "Technical Problem Review passed — on to topic 1.4", tone: "good" }] }, caption: "The Technical Problem Review as a walk-through. A missing piece sends you back to the lesson that owns it, never forward to solutions." },
    { t: "callout", tone: "key", title: "The thread through the topic", text: "Evidence first, explanation second, solution never — not in this topic. Every lesson ends with a question a tech lead can answer yes or no, and every yes rests on something another engineer could check." },
    { t: "note", text: "Working with an agent changes the speed of this topic, not its rules. The agent can read logs, write queries and draft chains in minutes. It still can’t watch a clerk work or decide which cause is real. You do that." },
  ],
  sections: [
    /* ───────────────────────────── 1.3.1 ───────────────────────────── */
    {
      id: "discover.problem.reproduce", fid: "discover.problem.reproduce", code: "1.3.1", title: "Reproduce & Trace the Current Flow", minutes: 12,
      blocks: [
        { t: "lead", text: "There is a version of the problem everyone tells, and there is the one that happens. This lesson makes the problem happen on demand, in a safe place, and traces it step by step so you know exactly where in the flow it goes wrong." },
        { t: "tldr", items: [
          "Reproduce today’s flow on real, masked samples in a test environment — never in production.",
          "Trace every step with its system, the data going in and out, the time it takes, and whether a person does it by hand.",
          "Mark where it goes wrong, then hand the trace to another engineer to repeat.",
          "The output is the current flow trace; the gate is “Problem Reproduced”.",
          "A problem you can’t reproduce at all is a finding, not a dead end.",
        ] },
        { t: "p", text: "The job: *help me see the problem happen, so I’m not fixing a story about it.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Stories about a problem are compressed. People remember the bad days, merge three different failures into one, and leave out the steps they no longer notice because they do them every hour. None of that is dishonest; it’s how memory works. But if you design against the story, you design against a problem that may not exist in that shape." },
        { t: "p", text: "Reproducing the problem does three things for you. It proves the problem is real and not a one-off. It shows you exactly *where* in the flow it happens, which narrows everything that follows. And it gives you a repeatable setup you’ll reuse — to measure the baseline in the next lesson, to test causes after that, and much later to show that a fix actually worked." },
        { t: "figure", fig: { kind: "hub", center: "Reproducing the problem", items: [{ label: "Proves it’s real", icon: "verified", text: "The problem is real and not a one-off." }, { label: "Shows where", icon: "map", text: "Exactly where in the flow it happens, which narrows everything that follows." }, { label: "A repeatable setup", icon: "sync", text: "Reused to measure the baseline, to test causes, and later to show a fix worked." }] }, caption: "The three things reproduction gives you. The third pays off all the way to the end of the project." },
        { t: "pull", text: "If you haven’t seen it happen, you don’t know what you’re fixing." },
        { t: "p", text: "There’s a quieter benefit too. Watching the flow end to end almost always turns up something the data flow map missed: a spreadsheet nobody mentioned, a copy-paste between two windows, a step that only happens on Fridays. Those differences go in the learning log — they’re the reason you trace instead of trusting the map." },
        { t: "figure", fig: { kind: "split", left: { title: "The story", tone: "guess", items: ["Remembers the bad days", "Merges three failures into one", "Leaves out the hourly steps"] }, right: { title: "The trace", tone: "fact", items: ["A spreadsheet nobody mentioned", "Copy-paste between two windows", "A step that only happens on Fridays"] } }, caption: "Why you trace instead of trusting the story or the map: watching the flow end to end turns up what memory compresses away. The differences go in the learning log." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "This is the first lesson of the investigation. It starts once the **technical framing pack** from topic 1.2 has been accepted, and it uses the **data flow map** from topic 1.1 to know which systems and hops to look at. It needs **repository and environment access** — the read-only access requested in topic 1.1 — so you can run the flow somewhere safe and read its logs." },
        { t: "table", caption: "Inputs and outputs", head: ["", "Artifact", "Why you need it"], rows: [
          ["In", "Technical framing pack", "The agreed frame: what problem you’re investigating and what you’re not"],
          ["In", "Data flow map", "Which systems the flow touches, and which hops are manual (DF-##)"],
          ["In", "Repository & environment access", "A test environment, logs and read-only access to run the flow safely"],
          ["Out", "Current flow trace", "Every step with system, data, time and manual work — repeatable by someone else"],
          ["Evidence", "Tech lead review notes", "Proof that the trace was checked and accepted"],
        ] },
        { t: "figure", fig: { kind: "context", center: { label: "Reproduce & Trace", sub: "1.3.1" }, around: [{ label: "Technical framing pack", sub: "topic 1.2", type: "store", dir: "in", text: "What problem you’re investigating and what you’re not." }, { label: "Data flow map", sub: "DF-##", type: "store", dir: "in", text: "Which systems the flow touches, and which hops are manual." }, { label: "Repository & environment access", sub: "read-only", type: "system", dir: "in", text: "A test environment, logs and read-only access to run the flow safely." }, { label: "Current flow trace", type: "store", dir: "out", text: "Every step with system, data, time and manual work — repeatable by someone else." }, { label: "Tech lead review notes", type: "person", dir: "out", text: "Proof that the trace was checked and accepted." }] }, caption: "What flows into this lesson and what comes out. The framing pack and the map say where to look; the trace is what you hand on." },
        { t: "figure", fig: { kind: "workflow", fid: "discover.problem.reproduce" }, caption: "The lesson’s workflow: pick samples, reproduce safely, trace each step, then decide whether it’s reproduced reliably." },
        { t: "table", caption: "Who does what", head: ["Role", "RACI", "In this lesson"], rows: [
          ["Engineer", "Responsible", "Picks samples, reproduces the flow, writes the trace"],
          ["Tech lead", "Accountable", "Accepts the trace; escalates if production access is needed"],
          ["System owners", "Consulted", "Explain their systems, confirm test environments, grant access"],
          ["End users", "Consulted (observed)", "Do the manual steps while you watch and time them"],
          ["Architect", "Informed", "Sees where the flow differs from the architecture picture"],
        ] },

        { t: "h", text: "Key ideas" },
        { t: "terms", items: [
          { term: "Reproduction", def: "Making the problem happen on demand, from written steps, in an environment where nothing real can break." },
          { term: "Current flow trace", def: "A table of today’s flow, one row per step: what happens, which system (SYS-##), data in → out, manual or not, median time, and whether it goes wrong there." },
          { term: "Masked sample", def: "A real case with personal and commercial details replaced, so it still shows the problem but leaks nothing." },
          { term: "Manual step", def: "A step where a person moves, reads, types or decides. Most of the time and most of the errors usually sit in these." },
          { term: "Repeatable", def: "Another engineer, given only your written trace, can make the same thing happen and see the same result." },
          { term: "Time-and-motion study", def: "Timing real tasks step by step, with clear task boundaries, so effort can be compared like with like before and after a change." },
        ] },
        { t: "p", text: "Two pieces of standard knowledge help you here. The **C4 model** gives you the zoom level: for a trace, the container level — which app, service or store handles each step — is usually right. A **sequence diagram** is the natural picture of a trace: participants across the top, messages in order down the page, including the failure path. You don’t have to draw one, but thinking in sequences keeps you from skipping steps." },
        { t: "p", text: "The lesson’s states are worth naming, because each one is a small milestone: the problem starts **Described**, becomes **Reproduced** when you’ve made it happen, **Traced** when every step is written down, and **Repeatable** when someone else has done it from your notes." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Described", sub: "people tell it", tone: "risk" }, { label: "Reproduced", sub: "you made it happen", tone: "human" }, { label: "Traced", sub: "every step written down", tone: "system" }, { label: "Repeatable", sub: "someone else did it from your notes", tone: "new" }] }, caption: "The lesson’s four states. Each one is a small milestone, and only the last one passes the gate." },
        { t: "figure", fig: { kind: "knowledge", name: "Reproduce before you fix" }, caption: "Reproduce before you fix: a reproduction on named samples in a named environment, not a guess about where it’s slow." },

        { t: "h", text: "How to do it" },
        { t: "steps", items: [
          { title: "Pick real samples to reproduce with", text: "Choose a small, representative set: normal cases, a few edge cases, and cases you know went wrong. Real enough to show the problem, small enough to work through by hand. Then mask them — replace names, addresses, prices and anything personal — before they leave the place they belong. Write down where each sample came from and what you masked, so the set can be rebuilt.", tip: "Ask the people who do the work for one “typical” and one “awful” example. The awful ones show you the failure; the typical ones show you the time." },
          { title: "Reproduce the flow safely", text: "Run the flow in a test environment or a copy, never in production. Follow the real steps in the real order, with the real tools. Decide before you start what you’ll log or time at each step, so you capture it as it happens rather than reconstructing it afterwards. If there is no test environment at all, observe the real flow read-only and record it — you watch, you don’t touch.", tip: "Keep everything read-only on any live system. If you find yourself needing write access to production, stop and escalate." },
          { title: "Trace each step with its timing", text: "For every step write one row: what happens, which system it runs on (with its SYS ID), what data goes in and comes out, whether a person does it by hand, how long it takes (the median over your samples, not one run), and whether it goes wrong there. Link each row to the data flow (DF-##) it belongs to. Manual steps are where the time and the errors usually hide, so time them yourself — logs don’t see a person reading a PDF.", tip: "Tracing happens while you reproduce, not afterwards. A trace written from memory is a story with a table around it." },
          { title: "Mark where it goes wrong", text: "Go back over the rows and mark each step where the problem shows: a wrong value, a lost item, a long wait, a workaround. Be specific about the failure and its rate if you saw one, for example “wrong code picked, 1 in 60”. This column is what the next three lessons will lean on hardest." },
          { title: "Decide: is it reproduced reliably?", text: "Hand the trace to another engineer and ask them to repeat it from what’s written. If they get the same result, the tech lead can accept it. If they get stuck, something is missing — a step, a setting, a sample — so trace again with more detail. The test is not “does it look complete?” but “could someone else make it happen without asking me?”." },
        ] },
        { t: "figure", fig: { kind: "tree", root: "The sample set", children: [{ label: "What goes in", children: [{ label: "Normal cases", text: "The typical ones show you the time." }, { label: "Edge cases" }, { label: "Known failures", text: "The awful ones show you the failure." }] }, { label: "What gets masked", children: [{ label: "Names" }, { label: "Addresses" }, { label: "Prices" }, { label: "Anything personal" }] }, { label: "What you write down", children: [{ label: "Where each sample came from" }, { label: "What you masked", text: "So the set can be rebuilt." }] }] }, caption: "Step one, broken down: a small set real enough to show the problem, masked before it leaves its system, and recorded so it can be rebuilt." },
        { t: "contrast", label: "A trace row", bad: { title: "Weak", text: "“Clerk enters the order. Takes a while, sometimes mistakes.” No system, no data, no time, no rate — nobody can repeat it or measure against it." }, good: { title: "Strong", text: "“Step 3 · Clerk re-types lines into the ERP client · SYS-01 · PDF lines → order lines · Manual: yes · 9 min median · Goes wrong here: typos in qty / item (most errors).”" } },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "Step 3", label: "Step" }, { text: " · " }, { text: "Clerk re-types lines into the ERP client", label: "What happens" }, { text: " · " }, { text: "SYS-01", label: "System", note: "Its SYS ID" }, { text: " · " }, { text: "PDF lines → order lines", label: "Data in → out" }, { text: " · " }, { text: "Manual: yes", label: "Manual?", note: "Time it yourself — logs don’t see a person reading a PDF." }, { text: " · " }, { text: "9 min median", label: "Median time", note: "Over your samples, not one run." }, { text: " · " }, { text: "Goes wrong here: typos in qty / item (most errors)", label: "Goes wrong here", note: "Be specific, with a rate if you saw one." }] }, caption: "The strong trace row, part by part. Every column is something another engineer can repeat or measure against." },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Northwind’s clerks re-type emailed PDF orders into the ERP. The data flow map from topic 1.1 already said so (DF-02, manual). Now you make it happen. On **20 masked orders in the test tenant**, you follow each order from the Microsoft 365 inbox to the ERP and time every step." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Order email", sub: "Microsoft 365 inbox", tone: "system" }, { label: "Open the PDF", sub: "clerk", tone: "human" }, { label: "Re-type each line", sub: "clerk · 9 of 13 min", tone: "risk" }, { label: "Save in the ERP", sub: "ERP", tone: "system" }] }, caption: "Today’s flow, traced. Most of the time — and most of the errors — sit in one manual step." },
        { t: "table", caption: "Northwind’s current flow trace (from the flow-trace example)", head: ["Step", "What happens", "System", "Data in → out", "Manual?", "Median", "Goes wrong here?"], rows: [
          ["1", "Order e-mail lands in shared inbox", "SYS-02", "E-mail + PDF", "No", "—", ""],
          ["2", "Clerk opens PDF, finds customer code in spreadsheet", "SYS-04", "PDF → customer code", "Yes", "2.5 min", "Wrong code picked (1 in 60)"],
          ["3", "Clerk re-types lines into ERP client", "SYS-01", "PDF lines → order lines", "Yes", "9 min", "Typos in qty / item (most errors)"],
          ["4", "Clerk e-mails confirmation", "SYS-02", "Order no. → e-mail", "Yes", "1.5 min", ""],
        ] },
        { t: "figure", fig: { kind: "lanes", lanes: ["Shared inbox · SYS-02", "Clerk", "Spreadsheet · SYS-04", "ERP client · SYS-01"], steps: [{ lane: 0, label: "Order e-mail lands", sub: "E-mail + PDF" }, { lane: 1, label: "Opens the PDF", flag: "manual" }, { lane: 2, label: "Finds customer code", sub: "2.5 min · wrong code 1 in 60", flag: "error" }, { lane: 3, label: "Re-types the lines", sub: "9 min · most errors", flag: "error" }, { lane: 0, label: "E-mails confirmation", sub: "1.5 min", flag: "manual" }] }, caption: "Northwind’s trace by system: the clerk carries the order across three systems by hand, and the two error points sit in steps 2 and 3." },
        { t: "figure", fig: { kind: "bars", unit: "min", rows: [{ label: "Step 2 · find customer code", value: 2.5, max: 13, note: "2.5 min", tone: "neutral" }, { label: "Step 3 · re-type lines", value: 9, max: 13, note: "9 min", tone: "bad" }, { label: "Step 4 · e-mail confirmation", value: 1.5, max: 13, note: "1.5 min", tone: "neutral" }] }, caption: "Median minutes per manual step, out of 13. Step 3 alone takes 9 — that’s where the next lessons will look hardest." },
        { t: "callout", tone: "case", title: "Northwind", text: "On 20 masked orders in the test tenant, the trace shows 9 of 13 minutes spent re-typing lines and most errors at that step." },
        { t: "p", text: "Two things stand out. Three of the four steps are manual, and one of them — step 3 — takes most of the time and produces most of the errors. And step 2 shows something the data flow map didn’t make obvious: customer codes are looked up in a spreadsheet. That’s exactly the kind of difference between the map and the real flow that goes in the learning log." },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "Your agent is good at the parts of this lesson that are about text and logs: suggesting a sample set, writing masking rules, turning your rough notes into clean trace rows, and checking whether the trace could be repeated. It can’t watch a clerk work. Observe the manual steps yourself, and time them." },
        { t: "prompt", title: "Pick and mask the samples", text: "I’m reproducing today’s flow for [describe the flow] in a test environment.\nHelp me pick a small, representative set of real samples to reproduce with: a few normal cases, a few edge cases and a few known failures.\nFor each sample type, say why it’s in the set.\nThen tell me exactly which fields to mask before using them, and how, so no personal or commercial data leaves its system.\nDon’t invent sample data — ask me for what you need.\n\nCheck in its answer: every masking rule covers a real field in your data; failing cases are included, not only clean ones; nothing suggests touching production." },
        { t: "prompt", title: "Turn notes into trace rows", text: "Here are my notes and log extracts from reproducing the flow on [N] masked samples: [paste].\nTurn them into flow-trace rows with these columns: step, what happens, system (SYS ID), data in → out, manual or not, median time, goes wrong here.\nUse only times and failures that appear in my notes. Where something is missing, write “unknown” and list it at the end as a question for me.\nThen check: could another engineer repeat this trace from what’s written? List anything missing.\n\nCheck in its answer: every time comes from your notes, not a guess; manual steps are marked; the “missing” list is real — go and fill it." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Your agent can generate masked samples, read logs and assemble the trace table. What it can’t do is watch a clerk work. Observe the manual steps yourself, and time them." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Tech lead"], steps: [{ lane: 1, label: "Suggests the sample set" }, { lane: 1, label: "Writes masking rules" }, { lane: 0, label: "Observes and times manual steps", flag: "manual" }, { lane: 1, label: "Turns notes into trace rows" }, { lane: 1, label: "Lists what’s missing", flag: "wait" }, { lane: 0, label: "Fills the gaps" }, { lane: 2, label: "Accepts the trace", flag: "ok" }] }, caption: "Who does what with an agent. The agent handles text and logs; watching and timing the clerk stays with you." },

        { t: "h", text: "When it goes off the path" },
        { t: "p", text: "The happy path is simple: the problem reproduces on the first sample set and the trace is clear. Real investigations wander. These are the routes the lesson already expects." },
        { t: "table", caption: "Routes out of this lesson", head: ["Situation", "Route", "What you do"], rows: [
          ["Trace is reliable", "Forward", "Hand the flow trace to 1.3.2 Measure the Baseline"],
          ["The flow is mostly manual", "Alternate", "Use a time-and-motion trace instead of logs"],
          ["Another engineer can’t repeat it", "Rework", "Trace again with more detail — logs and timestamps, not memory"],
          ["You need production access", "Escalate", "Tech lead and system owner decide; you don’t take it yourself"],
          ["The problem only appears under load", "Alternate", "Reproduce with a scripted batch"],
          ["Intermittent failure", "Edge case", "Collect several runs and their logs; compare what the failing runs share"],
          ["It can’t be reproduced at all", "Stop", "Back to framing with what you did see — recorded in the learning log"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [{ id: "q1", q: "Can you reproduce it at all?", yes: "q2", no: "stop" }, { id: "q2", q: "Do you need production access?", yes: "esc", no: "q3" }, { id: "q3", q: "Is the flow mostly manual?", yes: "tm", no: "q4" }, { id: "q4", q: "Does it only appear under load?", yes: "batch", no: "q5" }, { id: "q5", q: "Does it fail only some of the time?", yes: "runs", no: "q6" }, { id: "q6", q: "Can another engineer repeat it from your trace?", yes: "fwd", no: "rework" }, { id: "stop", result: "Stop: back to framing with what you did see, recorded in the learning log", tone: "bad" }, { id: "esc", result: "Escalate: the tech lead and system owner decide — you don’t take it yourself", tone: "neutral" }, { id: "tm", result: "Use a time-and-motion trace instead of logs", tone: "neutral" }, { id: "batch", result: "Reproduce with a scripted batch", tone: "neutral" }, { id: "runs", result: "Collect several runs and their logs; compare what the failing runs share", tone: "neutral" }, { id: "fwd", result: "Forward: hand the trace to 1.3.2 Measure the Baseline", tone: "good" }, { id: "rework", result: "Rework: trace again with logs and timestamps, not memory", tone: "bad" }] }, caption: "The routes out of this lesson as questions. Production access is never your call; a problem you can’t reproduce is a finding that sends you back to framing." },
        { t: "callout", tone: "warn", title: "Reproduce before you fix", text: "If you haven’t seen it happen, you don’t know what you’re fixing. A problem you can’t reproduce at all is itself a finding — and it changes the plan." },
        { t: "p", text: "Intermittent problems need more than one run. Collect several runs and their logs, and look for what the failing ones have in common: a time of day, a sender, a file type, a size. If the samples contain personal data you didn’t notice, the recovery is simple and non-negotiable: mask and re-run." },
        { t: "figure", fig: { kind: "knowledge", name: "Time-and-motion study" }, caption: "Time-and-motion study: what each step takes, and where people do the work by hand — timed with clear boundaries so it can be compared later." },

        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "Writing the trace from memory after the session.", fix: "Trace while you reproduce, with logs and timestamps open. Repeat with them if you already wrote it from memory." },
          { trap: "Using real orders with customer names and prices still in them.", fix: "Mask before use. If personal data slipped through, mask and re-run — don’t just delete the file." },
          { trap: "Tracing only the systems, because that’s what the logs show.", fix: "Sit with the people doing the work and time the manual steps. They’re usually where the problem is." },
          { trap: "Reproducing only clean, typical cases.", fix: "Include edge cases and known failures in the sample set, or you’ll trace a flow that works." },
          { trap: "Reaching for production when the test environment is awkward.", fix: "Escalate to the tech lead and system owner. Read-only observation is the fallback, not quiet production access." },
          { trap: "Starting to fix things the moment you see the problem.", fix: "Write it down and keep tracing. You don’t yet know how much it matters or why it happens." },
        ] },
        { t: "figure", fig: { kind: "template", id: "flow-trace" }, caption: "The current flow trace — every step with system, data and time, manual steps and failure points marked." },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["Every step has its system, timing and data", "Manual steps are marked", "Someone else can reproduce it from the trace", "Only masked data was used"] },
        { t: "p", text: "A useful measure for yourself is **time to first reproduction**: how long it took from starting the lesson to seeing the problem happen once. If it took most of the timebox, note why in the learning log — slow access or a missing test environment will slow every later lesson too." },
        { t: "try", text: "Trace the four steps of handling one order, with system, data and median time for each. Then do the same for your own project." },

        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Problem Reproduced", items: [
          "The problem was reproduced in a test environment or on real, masked samples",
          "Every trace row has what happens, system (SYS ID), data in → out, manual or not, and median time",
          "Steps where it goes wrong are marked, with a rate where you saw one",
          "Trace steps link to DF-## and SYS-##",
          "Another engineer repeated the trace from what’s written",
          "Differences between the real flow and the map are in the learning log",
          "The tech lead accepted the trace",
        ] },
      ],
    },

    /* ───────────────────────────── 1.3.2 ───────────────────────────── */
    {
      id: "discover.problem.baseline", fid: "discover.problem.baseline", code: "1.3.2", title: "Measure the Baseline", minutes: 10,
      blocks: [
        { t: "lead", text: "“It takes ages” is an anecdote. “Median 13 minutes, p95 24, over two weeks of timestamps” is a baseline. This lesson replaces estimates with measurements, so the problem — and later every option — is judged against today’s real numbers." },
        { t: "tldr", items: [
          "Measure each success metric from topic 1.2, using data that already exists — logs, databases, timestamps, credit notes.",
          "Every number carries its method, sample size, period and source.",
          "Report medians and percentiles (p95), not averages alone — the slow tail is what people feel.",
          "Write the method so another engineer can re-run it later, unchanged.",
          "Measure before you change anything: once the system changes, “before” is gone.",
        ] },
        { t: "p", text: "The job: *help me know how bad it really is today, in numbers I can defend.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Every decision after this topic will be argued in numbers. Option A is faster than option B — faster than what? The pilot cut errors — from what? Without a baseline those sentences have nothing underneath them, and the loudest opinion wins." },
        { t: "p", text: "A baseline also tells you whether the problem is as big as the brief said. Sometimes it is bigger. Sometimes it is much smaller, and that is one of the most valuable findings Discover can produce, because it saves a build nobody needed." },
        { t: "callout", tone: "warn", title: "Measure before you change anything", text: "Once you start changing the system, you can never measure “before” again. Measure first." },
        { t: "p", text: "And the baseline is reused. The same method you write here is what VERIFY and later stages re-run to show the solution worked. A baseline that can’t be re-run isn’t really a baseline; it’s a number someone once saw." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Measure now", sub: "method written down", tone: "human" }, { label: "Change the system", sub: "“before” is gone", tone: "risk" }, { label: "Re-run the same method", sub: "VERIFY and later stages", tone: "system" }, { label: "Show it worked", sub: "against today’s numbers", tone: "new" }] }, caption: "Why the baseline must be re-runnable: the method you write here is the one that later proves the solution worked. Measure before anything changes." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "You start once the flow has been reproduced. The **current flow trace** tells you where in the flow to measure — between which two steps, on which system. The **technical success metrics** from topic 1.2 tell you *what* to measure: each metric already has a target and a planned method, and most have a rough baseline marked “to confirm”. This lesson confirms or replaces those rough numbers." },
        { t: "figure", fig: { kind: "context", center: { label: "Measure the Baseline", sub: "1.3.2" }, around: [{ label: "Current flow trace", type: "store", dir: "in", text: "Where to measure — between which two steps, on which system." }, { label: "Technical success metrics", sub: "M-##", type: "store", dir: "in", text: "What to measure: each with a target, a planned method and a rough baseline “to confirm”." }, { label: "Data owner", type: "person", dir: "in", link: "read access", text: "Grants read access and explains what the data really means." }, { label: "Baseline measurements", type: "store", dir: "out", text: "Rough numbers confirmed or replaced." }, { label: "Client contact", type: "person", dir: "out", link: "hears the numbers", text: "Especially if they differ from the brief." }] }, caption: "The trace says where to measure, the metrics say what. Queries stay read-only and personal data is aggregated." },
        { t: "figure", fig: { kind: "workflow", fid: "discover.problem.baseline" }, caption: "The lesson’s workflow: pick metrics and sources, pull a representative sample, compute medians, p95 and error rates, then decide whether the baseline can be trusted." },
        { t: "table", caption: "Who does what", head: ["Role", "RACI", "In this lesson"], rows: [
          ["Engineer", "Responsible", "Writes the queries and methods, pulls the sample, computes the numbers"],
          ["Tech lead", "Accountable", "Checks the method and accepts the baseline"],
          ["Data owner", "Consulted", "Grants read access and explains what the data really means"],
          ["Client contact", "Informed", "Hears the numbers — especially if they differ from the brief"],
        ] },
        { t: "p", text: "The policy is simple and strict: **read-only queries, and personal data aggregated**. You count and time; you don’t copy customer records into a spreadsheet." },

        { t: "h", text: "Key ideas" },
        { t: "terms", items: [
          { term: "Baseline", def: "Today’s measured value of a success metric, with the method, sample, period and source that produced it." },
          { term: "Median", def: "The middle value when all observations are sorted — half took less, half took more. Not pulled about by a few extreme cases." },
          { term: "p95", def: "The 95th percentile: 95% of observations are at or below it. It describes the slow tail — the cases people remember and complain about." },
          { term: "Error rate", def: "Failures divided by the total, over a stated period — for example wrong lines out of all lines entered." },
          { term: "Representative sample", def: "A period and set of cases that reflect the load the solution will face, including normal and peak." },
          { term: "Confidence", def: "How much you trust a number, stated openly: full logs over two weeks are high; a hand-timed handful is lower and gets a wider range." },
        ] },
        { t: "figure", fig: { kind: "hub", center: "A baseline number", items: [{ label: "Method", icon: "rule", text: "The exact query or method, so it can be re-run." }, { label: "Sample", icon: "filter_alt", text: "A representative set covering normal and peak load." }, { label: "Period", icon: "schedule", text: "The stated span the number covers." }, { label: "Source", icon: "database", text: "Where the data already lives: logs, databases, timestamps." }, { label: "Median and p95", icon: "query_stats", text: "What’s typical and what’s bad; errors as rates." }, { label: "Confidence", icon: "verified", text: "Stated openly: full logs are high, a hand-timed handful is lower." }] }, caption: "What a baseline carries besides the number. Without these, a number is just something someone once saw." },
        { t: "h3", text: "Why not just the average?" },
        { t: "p", text: "Averages hide the slow tail. A process where most items take a few minutes but one in twenty takes half an hour has a modest average and a terrible experience for whoever handles that one in twenty. The median tells you what’s typical; the p95 tells you what’s bad. Report both. If you want the average too, add it — just never alone." },
        { t: "figure", fig: { kind: "split", left: { title: "Average alone", tone: "bad", items: ["Hides the slow tail", "Looks modest when one in twenty takes half an hour", "Pulled about by extreme cases"] }, right: { title: "Median and p95", tone: "good", items: ["Median: what’s typical", "p95: what’s bad", "Add the average if you like — never alone"] } }, caption: "Why the baseline reports both. The tail is the part people feel and complain about." },
        { t: "p", text: "Computing them is standard. Sort the observations; the median is the middle one (or the mean of the two middle ones). For p95, take the value below which 95% of observations fall — most databases and spreadsheets have a percentile function, and you should name which one you used, since methods differ slightly at small sample sizes." },
        { t: "h3", text: "Where good metrics come from" },
        { t: "p", text: "**Goal–Question–Metric** keeps measurement honest: start from the goal (cut order-handling effort), ask the question that shows whether it’s met (how long does an order take now?), and only then pick the metric that answers it (median minutes from email received to order in the ERP). The **golden signals** — latency, traffic, errors, saturation — are a good checklist for anything a system does. And **measure what users feel**: time the thing a person waits for, not a server statistic that happens to be easy to graph." },
        { t: "figure", fig: { kind: "stack", layers: [{ label: "Goal", sub: "Cut order-handling effort" }, { label: "Question", sub: "How long does an order take now?" }, { label: "Metric", sub: "Median minutes from email received to order in the ERP" }] }, caption: "Goal–Question–Metric, top down: the metric is picked last, only once the goal and the question are clear." },
        { t: "figure", fig: { kind: "knowledge", name: "Golden signals" }, caption: "The golden signals: latency, traffic, errors, saturation — a good starting set for any baseline." },

        { t: "h", text: "How to do it" },
        { t: "steps", items: [
          { title: "Pick the metrics and their data sources", text: "Start from the success metrics you set in topic 1.2. For each one, find where the real data already lives: timestamps in a mailbox and an ERP, error reasons on credit notes, ticket histories, application logs. Write the exact query or method — which table or log, which fields, which filter, how you match one record to another. If no logs exist for a metric, you can time a sample by hand, but say so next to the number.", tip: "Use existing logs before building new probes. New instrumentation takes time and changes the thing you’re measuring." },
          { title: "Pull a representative sample", text: "Choose a period long enough to be fair and covering the load that matters — normal weeks and, if the work is seasonal, peak. Write down what would make the sample unrepresentative: a holiday, an outage, a quiet week, a one-off promotion. Several metrics can be pulled in parallel from different sources; just keep the period the same so they can be compared.", tip: "If volumes are seasonal, measure peak and normal separately. A system that copes in March and breaks in November is the whole problem." },
          { title: "Compute medians, p95 and error rates", text: "For each metric, compute the median and p95 for times, and rates for errors — failures over total, for the same period. Fill a baseline row per metric: metric, method, period, sample size, median, p95 (or rate), source and confidence. If the data is partial, state the coverage and lower the confidence rather than quietly using what you have.", tip: "Keep the raw results. Someone will ask to see them." },
          { title: "Record the method", text: "Write the method so another engineer could re-run it next month with no help: the query text, the matching rule, the percentile function, the period, any exclusions and why. Link each baseline to its metric (M-##). This is the part people skip, and it’s the part that makes the number reusable." },
          { title: "Decide: is the baseline trustworthy?", text: "The tech lead checks the method for bias and gaps. Is the sample from a quiet week? Are averages hiding a tail? Could someone re-run the query? An unrepresentative sample is re-pulled. If you need data you can’t access, go to its owner — don’t work around access controls. If the numbers show no real problem, that’s a stop: back to framing, recorded in the learning log." },
        ] },
        { t: "figure", fig: { kind: "tree", root: "Where a metric’s data already lives", children: [{ label: "Timestamps", text: "In a mailbox and an ERP." }, { label: "Error reasons", text: "On credit notes." }, { label: "Ticket histories" }, { label: "Application logs" }, { label: "No logs?", text: "Time a sample by hand — and say so next to the number." }] }, caption: "Step one: use data that already exists before building new probes. A hand-timed sample is allowed, but it is labelled." },
        { t: "contrast", label: "A baseline number", bad: { title: "Weak", text: "“Orders take about 14 minutes on average.” Whose estimate? Over what period? How many orders? Can anyone check it?" }, good: { title: "Strong", text: "“M-1 clerk minutes per order: median 13, p95 24. Method: ERP created timestamp minus inbox received timestamp. Period: two weeks. Source: mailbox and ERP timestamps. Re-runnable query attached.”" } },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "M-1 clerk minutes per order: ", label: "Metric", note: "Linked to its M-##." }, { text: "median 13, p95 24. ", label: "Result", note: "Median and p95, not an average." }, { text: "Method: ERP created timestamp minus inbox received timestamp. ", label: "Method" }, { text: "Period: two weeks. ", label: "Period" }, { text: "Source: mailbox and ERP timestamps. ", label: "Source" }, { text: "Re-runnable query attached.", label: "Re-runnable", note: "The part people skip, and the part that makes it reusable." }] }, caption: "The strong baseline number, part by part. Each part answers a question the weak version left open." },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Topic 1.2 left Northwind with three success metrics, two of them with rough baselines “to confirm” and one simply unknown. This lesson replaces all three with measurements." },
        { t: "table", caption: "From estimate to measurement", head: ["Metric", "Topic 1.2 said", "Method (from the success metrics)", "Measured today", "Target"], rows: [
          ["M-1 Clerk minutes per e-mail order", "~14 min (to confirm)", "ERP timestamps vs inbox received", "Median 13 min, p95 24 — two weeks of timestamps", "≤ 5 min"],
          ["M-2 Order lines entered wrongly", "3% (to confirm)", "Credit notes with “wrong line” reason", "3.1% of lines", "≤ 1%"],
          ["M-3 Orders lost or duplicated", "unknown", "Inbox IDs reconciled with ERP orders daily", "0.4% of inbox orders never reach the ERP", "0"],
        ] },
        { t: "figure", fig: { kind: "delta", beforeLabel: "Measured today", afterLabel: "Target", rows: [{ label: "M-1 clerk minutes per order (median)", before: 13, after: 5, unit: "min", better: "lower" }, { label: "M-2 order lines entered wrongly", before: 3.1, after: 1, unit: "%", better: "lower" }, { label: "M-3 orders lost (never reach the ERP)", before: 0.4, after: 0, unit: "%", better: "lower" }] }, caption: "Northwind’s three metrics, today against target. Every “today” now has a method behind it, including M-3, which nobody could answer before." },
        { t: "figure", fig: { kind: "bars", rows: [{ label: "Median time per order", value: 13, max: 26, note: "13 min", tone: "neutral" }, { label: "p95 time per order", value: 24, max: 26, note: "24 min", tone: "bad" }, { label: "Wrong order lines", value: 3.1, max: 4, note: "3.1%", tone: "bad" }, { label: "Orders never reaching the ERP", value: 0.4, max: 4, note: "0.4%", tone: "bad" }] }, caption: "Northwind’s baseline. Each number has a method, a sample and a period behind it." },
        { t: "callout", tone: "case", title: "Northwind", text: "Two weeks of timestamps: median 13 min, p95 24; credit notes: 3.1% wrong lines; 0.4% of inbox orders never reach the ERP." },
        { t: "p", text: "Notice what changed. The estimate of ~14 minutes was close, and now it has a method behind it. The 3% guess holds up as 3.1%. And the metric nobody could answer — lost orders — now has a number, which matters because QA-2 says no order may be lost. The p95 of 24 minutes is nearly twice the median: the slow tail is real, and an average would have hidden it." },
        { t: "figure", fig: { kind: "knowledge", name: "Baseline measurement" }, caption: "Baseline measurement: metric, method, period, sample, median and p95 in one row — the shape every baseline should take." },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "Agents are excellent at writing queries and doing the arithmetic. They’re also capable of producing a confident number from a query that joins the wrong tables. Keep the three things separate — the query, the sample definition and the result — and re-run the query yourself." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Tech lead"], steps: [{ lane: 1, label: "Writes the query", sub: "read-only" }, { lane: 0, label: "Re-runs the query yourself", flag: "manual" }, { lane: 1, label: "Computes median, p95, rate", sub: "names the percentile method" }, { lane: 0, label: "Recomputes one value by hand", flag: "manual" }, { lane: 1, label: "Checks for bias and gaps" }, { lane: 2, label: "Checks the method, accepts", flag: "ok" }] }, caption: "Query, sample definition and result kept separate. The agent does the arithmetic; you re-run and recompute before the tech lead sees it." },
        { t: "prompt", title: "Write the methods", text: "Here are my success metrics, with their targets and planned methods: [paste M-## rows].\nHere is my current flow trace: [paste].\nFor each metric, tell me the best data source (logs, database or a timed sample) and write the exact query or method to measure it, including how records are matched between systems.\nRead-only queries only, and aggregate any personal data.\nFor each, say what would make the result misleading.\n\nCheck in its answer: each query reads from a source you actually have; the matching rule is explicit; nothing writes to a live system; run each query yourself before trusting it." },
        { t: "prompt", title: "Compute and challenge", text: "Here are the raw results for [metric] over [period]: [paste or attach].\nCompute the median, p95 and (for errors) the rate, and say which percentile method you used.\nFill a baseline row: metric, method, period, sample size, median, p95, source, confidence.\nThen check my baseline for bias or gaps — quiet periods, missing data, peak not covered — before my tech lead reviews it.\n\nCheck in its answer: recompute one number yourself; the sample size matches what you pasted; any gap it names is real and either fixed or stated." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Agents are excellent at writing the queries and the calculation. Ask for the query, the sample definition and the result separately, and re-run the query yourself — a baseline someone can’t re-run is just another anecdote." },

        { t: "h", text: "When it goes off the path" },
        { t: "table", caption: "Routes out of this lesson", head: ["Situation", "Route", "What you do"], rows: [
          ["Logs give clean data for every metric", "Forward", "Hand the baseline measurements to 1.3.3 Find the Root Causes"],
          ["No logs for a metric", "Alternate", "Time a sample by hand, say so, and give a wider confidence range"],
          ["Data is partial", "Exception", "State the coverage and the confidence next to the number"],
          ["Sample unrepresentative (a quiet week, peak missing)", "Rework", "Re-pull covering normal and peak"],
          ["Seasonal volumes", "Edge case", "Measure peak and normal separately"],
          ["You need data you can’t access", "Escalate", "Go to the data owner; they grant read access"],
          ["The numbers show no real problem", "Stop", "Back to framing — recorded in the learning log"],
          ["No metric can be measured at all", "Failure", "Raise it with the tech lead: the metrics or the access need rethinking"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [{ id: "q1", q: "Can any metric be measured at all?", yes: "q2", no: "fail" }, { id: "q2", q: "Do you need data you can’t access?", yes: "esc", no: "q3" }, { id: "q3", q: "Are there logs for every metric?", yes: "q4", no: "hand" }, { id: "q4", q: "Does the sample cover normal and peak?", yes: "q5", no: "repull" }, { id: "q5", q: "Is the data complete?", yes: "q6", no: "partial" }, { id: "q6", q: "Do the numbers show a real problem?", yes: "fwd", no: "stop" }, { id: "fail", result: "Failure: raise it with the tech lead — the metrics or the access need rethinking", tone: "bad" }, { id: "esc", result: "Escalate: go to the data owner for read access", tone: "neutral" }, { id: "hand", result: "Time a sample by hand, say so, and give a wider confidence range", tone: "neutral" }, { id: "repull", result: "Rework: re-pull covering normal and peak (seasonal: measure them separately)", tone: "bad" }, { id: "partial", result: "State the coverage and the confidence next to the number", tone: "neutral" }, { id: "stop", result: "Stop: back to framing, recorded in the learning log", tone: "bad" }, { id: "fwd", result: "Forward: hand the baseline to 1.3.3 Find the Root Causes", tone: "good" }] }, caption: "The routes out of this lesson as questions. Access problems go to the data owner, never around access controls; no real problem is a stop, not a failure." },

        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "Reporting averages only.", fix: "Add the median and p95. If the p95 is far above the median, say so — that tail is part of the problem." },
          { trap: "Sampling the quietest week because the data was easy to get.", fix: "Re-pull a period covering normal and peak load, or label the baseline as unrepresentative." },
          { trap: "A number with no method next to it.", fix: "Write the query, period, sample size and source for every number, and link it to its M-##." },
          { trap: "Trusting an agent’s figure without re-running the query.", fix: "Re-run it yourself and recompute at least one value by hand." },
          { trap: "Copying personal records into a spreadsheet to “analyse later”.", fix: "Aggregate in the query. You need counts and times, not names." },
          { trap: "Changing something “small” before measuring.", fix: "Measure first. You can’t go back and measure before." },
        ] },
        { t: "note", text: "Metrics that turned out hard to measure go in the learning log. They’re a warning for later stages, which will need to measure the same thing again." },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["Every number has a method, a sample size and a period", "Medians and percentiles, not averages alone", "The method can be re-run later"] },
        { t: "try", text: "Write the query or method for “orders lost or duplicated” and the period you’d use. Then do the same for your own project." },

        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Baseline Trusted", items: [
          "Every success metric has a measured baseline, linked to its M-##",
          "Each number has its method, sample size, period and source",
          "Times are reported as median and p95; errors as rates",
          "The sample covers normal and, where it matters, peak load",
          "Partial data or hand timings are labelled with their confidence",
          "Queries were read-only and personal data aggregated",
          "The tech lead checked the method and accepted the baseline",
        ] },
      ],
    },

    /* ───────────────────────────── 1.3.3 ───────────────────────────── */
    {
      id: "discover.problem.causes", fid: "discover.problem.causes", code: "1.3.3", title: "Find the Root Causes", minutes: 10,
      blocks: [
        { t: "lead", text: "Symptoms are what people see: slow orders, wrong lines, lost emails. Causes are what in the system produces them. This lesson traces each symptom down to its cause, and keeps only the causes the evidence supports." },
        { t: "tldr", items: [
          "List the symptoms straight from the trace and the baseline, each with its number.",
          "Run a why-chain on each symptom until you reach a system condition you could change — never a person.",
          "Sort causes by category: data, integration, code, infrastructure, manual step.",
          "Keep only causes the trace, baseline or logs actually show, and rank them by how much of the baseline they explain.",
          "Causes in vendor systems become constraints; non-technical causes go back to the people who own them.",
        ] },
        { t: "p", text: "The job: *help me find what actually causes this, so the solution hits the cause.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Fix a symptom and it comes back in a new shape. Fix a cause and several symptoms disappear together. A team that treats symptoms spends its time on patches — a validation rule here, a reminder email there — while the thing producing the problem carries on." },
        { t: "figure", fig: { kind: "split", left: { title: "Fix a symptom", tone: "bad", items: ["It comes back in a new shape", "Time goes on patches: a validation rule, a reminder email", "The thing producing it carries on"] }, right: { title: "Fix a cause", tone: "good", items: ["Several symptoms disappear together", "The solution hits what produces the problem"] } }, caption: "Patching symptoms versus fixing causes. The left column is busy work; the right one changes the numbers." },
        { t: "p", text: "Root causes also decide which solutions are even worth researching in the next topic. If the cause of errors is that data is typed by hand, no amount of training will fix it, and a solution that still involves re-typing is ruled out before anyone builds it. That’s the point: a good cause analysis makes the option space smaller and sharper." },
        { t: "figure", fig: { kind: "funnel", stages: [{ label: "Every solution someone might propose" }, { label: "Training ruled out", items: ["Cause: data is typed by hand"] }, { label: "Re-typing solutions ruled out", items: ["Ruled out before anyone builds them"] }, { label: "A smaller, sharper option space" }] }, caption: "How a good cause analysis narrows the next topic’s research. Once the cause is hand typing, options that keep it drop out on their own." },
        { t: "pull", text: "Fix a symptom and it comes back. Fix a cause and several symptoms go together." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "You start once the baseline is trusted. The **current flow trace** shows where things go wrong; the **baseline measurements** show how much. Both are your evidence. The output is the **technical root-cause analysis**: symptoms, why-chains, causes by category, the evidence for each, and a ranking by contribution. Each cause gets an ID (RC-##) linked to trace steps and baselines." },
        { t: "figure", fig: { kind: "tree", root: "Technical root-cause analysis", children: [{ label: "Symptoms", text: "From the trace and the baseline, each with its number." }, { label: "Why-chains", text: "From each symptom down to a system condition." }, { label: "Causes by category", children: [{ label: "RC-##", text: "Linked to trace steps and baselines." }] }, { label: "Evidence for each" }, { label: "Ranking by contribution" }] }, caption: "What the lesson produces. Every cause gets an RC ID that ties it back to the trace and the baseline it explains." },
        { t: "figure", fig: { kind: "workflow", fid: "discover.problem.causes" }, caption: "The lesson’s workflow: list symptoms, run why-chains, check each cause against evidence, then decide whether the causes are evidenced." },
        { t: "table", caption: "Who does what", head: ["Role", "RACI", "In this lesson"], rows: [
          ["Engineer", "Responsible", "Lists symptoms, builds why-chains, gathers evidence, ranks causes"],
          ["Tech lead", "Accountable", "Challenges the causes and accepts the analysis"],
          ["Architect", "Consulted", "Checks that causes are framed in system terms and explain the baseline"],
          ["System owners", "Consulted", "Confirm causes inside their systems — especially vendor ones"],
          ["Client contact", "Informed", "Hears the causes, and receives any that aren’t technical"],
        ] },

        { t: "h", text: "Key ideas" },
        { t: "terms", items: [
          { term: "Symptom", def: "What people see and measure: a time, an error rate, a loss. It comes from the trace and the baseline." },
          { term: "Root cause", def: "A condition in the system — data, integration, code, infrastructure or a manual step — that produces one or more symptoms and could be changed." },
          { term: "Why-chain", def: "A sequence of “why?” questions from a symptom down to a cause. The Five Whys is the classic form; the number five is a guide, not a rule." },
          { term: "Contributing cause", def: "A cause that adds to a symptom without explaining all of it. Most real problems have one or two big causes and a few contributors." },
          { term: "Evidence", def: "A trace step, a baseline number or a log entry that shows the cause at work. A cause without it is a theory." },
          { term: "Contribution", def: "How much of the baseline a cause explains — for example the share of handling time or errors it accounts for." },
        ] },
        { t: "h3", text: "Three tools, one job" },
        { t: "p", text: "**Five Whys** goes deep on one symptom: ask why it happens, then why that happens, until you reach something you can act on. The **fishbone diagram** goes wide: it puts the symptom at the head and groups possible causes along category bones, so you don’t stop at the first plausible one. **Kepner-Tregoe problem analysis** sharpens the search by comparing where the problem *is* with where it could be but *is not* — what’s distinctive about the cases that fail?" },
        { t: "figure", fig: { kind: "tree", root: "Three tools, one job", children: [{ label: "Five Whys", text: "Goes deep on one symptom — use it to dig." }, { label: "Fishbone diagram", text: "Goes wide across categories — use it to see the field." }, { label: "Kepner-Tregoe", text: "Where the problem is versus where it is not — use it when evidence is mixed." }] }, caption: "Each tool has its moment: the fishbone to see the field, the why-chains to dig, and the is / is-not comparison when the evidence is mixed." },
        { t: "p", text: "Use the fishbone to see the field, the why-chains to dig, and the is / is-not comparison when evidence is mixed. In this program the categories are fixed so causes stay comparable across projects: **data, integration, code, infrastructure, manual step**." },
        { t: "figure", fig: { kind: "hub", center: "Cause categories", items: [{ label: "Data", icon: "database", text: "A data shape that produces the symptom." }, { label: "Integration", icon: "integration_instructions", text: "A missing integration between systems." }, { label: "Code", icon: "bug_report", text: "A code defect." }, { label: "Infrastructure", icon: "dns", text: "An infrastructure limit." }, { label: "Manual step", icon: "person", text: "A step where a person moves, reads, types or decides — the step, never the person." }] }, caption: "The five fixed categories. Keeping them fixed makes causes comparable across projects." },
        { t: "figure", fig: { kind: "knowledge", name: "Fishbone diagram" }, caption: "The fishbone: contributing causes grouped by category, all pointing at one effect." },
        { t: "callout", tone: "warn", title: "Blame the system, not the person", text: "“The clerks make mistakes” is a symptom. Why does the work make mistakes likely? That question leads somewhere you can fix." },

        { t: "h", text: "How to do it" },
        { t: "steps", items: [
          { title: "List the symptoms", text: "Take them straight from the trace and the baseline, each with its number: how long, how often, how many lost. Don’t add symptoms nobody measured. If a symptom matters but has no number, that’s a gap in the baseline, not a symptom to analyse yet.", tip: "One line per symptom, with the number and where it came from — trace step or baseline row." },
          { title: "Run why-chains on each", text: "For each symptom, ask why until you reach a system condition: a data shape, a missing integration, a code defect, an infrastructure limit, or a manual step. Never stop at a person. Why-chains for different symptoms can run in parallel, and they often converge on the same cause — that convergence is a strong signal. Sort each cause into its category and note any that sit inside a vendor system.", tip: "If a chain ends at “someone made a mistake”, ask one more why: what about the work made the mistake likely?" },
          { title: "Check each cause against the evidence", text: "For every cause, find the trace step, baseline number or log entry that shows it. Write the evidence next to the cause. A cause you can’t point at is a theory — go back to the trace and dig again, or mark it unproven. Where the evidence is mixed, say so and mark your confidence.", tip: "Ask the opposite question too: if this cause were true, what else would we see? Do we see it?" },
          { title: "Rank by contribution", text: "Estimate how much of the baseline each cause explains — share of time, share of errors — and rank them. Usually two or three causes explain most of it. If one cause dominates, still check for contributors; they’re cheap to note now and expensive to discover after the build." },
          { title: "Decide: are the causes evidenced?", text: "The tech lead challenges the list: which of these are symptoms in disguise? Which lack evidence? Do the causes together explain most of the baseline? Unevidenced causes go back to the why-chains. A cause in a system you can’t change is escalated and recorded as a constraint. A cause that isn’t technical at all — training, policy — stops here and goes back to the client." },
        ] },
        { t: "figure", fig: { kind: "cycle", center: "Until every cause is evidenced", steps: [{ label: "Run the why-chain", text: "Down to a system condition, never a person." }, { label: "Point at the evidence", text: "A trace step, baseline number or log entry." }, { label: "Ask the opposite", text: "If this cause were true, what else would we see? Do we see it?" }, { label: "No evidence? Dig again", text: "Back to the trace, or mark it unproven." }] }, caption: "The loop inside steps two to five. A cause without evidence is a theory, and theories go round again." },
        { t: "contrast", label: "Where a why-chain stops", bad: { title: "Stops at a person", text: "“Lines are wrong because clerks make typing mistakes.” True, unfixable, and it points at training — which won’t change the error rate of re-typing by hand." }, good: { title: "Stops at a system condition", text: "“Lines are wrong because they’re typed by hand, because there’s no structured input, because orders arrive as PDF and the ERP only accepts API input.”" } },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Northwind’s symptoms come straight from the trace and the baseline: 13 minutes median per order, 3.1% wrong lines, 0.4% of orders missing. The why-chain on wrong lines is short and clear." },
        { t: "figure", fig: { kind: "ladder", top: "3.1% of order lines are wrong", rungs: ["Lines are typed by hand", "There is no structured input to copy from"], bottom: "Orders arrive as PDF, and the ERP only accepts API input" }, caption: "The why-chain for wrong lines, from the root-cause analysis. It ends at a condition in the system, not at the clerks." },
        { t: "table", caption: "Northwind’s causes, by category, with evidence", head: ["ID", "Category", "Cause", "Evidence"], rows: [
          ["RC-1", "Data", "Orders arrive unstructured (PDF)", "Trace steps 2–3"],
          ["RC-2", "Integration", "No path from the inbox to the ERP API", "Integration inventory INT-01/02"],
          ["RC-3", "Data", "Customer codes live only in personal spreadsheets", "Trace step 2: 1 in 60 wrong codes"],
        ] },
        { t: "figure", fig: { kind: "fishbone", effect: "13 min median, 3.1% wrong lines, 0.4% orders missing", bones: [{ label: "Data", causes: ["RC-1 orders arrive unstructured (PDF)", "RC-3 customer codes only in personal spreadsheets"] }, { label: "Integration", causes: ["RC-2 no path from the inbox to the ERP API"] }] }, caption: "Northwind’s evidenced causes on their category bones. Two of the five categories hold everything; none of the bones names a person or a tool." },
        { t: "figure", fig: { kind: "bars", unit: "%", rows: [{ label: "Handling time explained by RC-1 + RC-2", value: 85, max: 100, note: "~85%", tone: "bad" }, { label: "Errors explained by RC-1 + RC-2", value: 80, max: 100, note: "~80%", tone: "bad" }] }, caption: "Ranked by contribution: two causes explain most of the baseline. RC-3 is a smaller contributor, but it’s evidenced, so it stays." },
        { t: "callout", tone: "case", title: "Northwind", text: "RC-1 unstructured orders and RC-2 no path to the import API explain ~85% of the time and ~80% of the errors." },
        { t: "p", text: "The cause isn’t the clerks. It’s that orders arrive unstructured and there’s no path into the ERP’s import API. Notice how this connects back: C-01 (orders enter the ERP only through its REST import API) is a constraint you confirmed in topic 1.1, and RC-2 is the missing piece around it. And the “use an AI tool” request from topic 1.2 is nowhere in the causes — the analysis talks about conditions, not tools." },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "Agents are good at clustering symptoms, proposing why-chains and spotting chains that converge. They’re also good at producing plausible causes with no evidence at all. Ask for the chains first; then, separately, ask it to point at the evidence for each cause. Anything it can’t point at goes back in the pile." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Tech lead"], steps: [{ lane: 1, label: "Lists symptoms with numbers" }, { lane: 1, label: "Proposes why-chains", sub: "no evidence yet" }, { lane: 1, label: "Points at evidence — separately" }, { lane: 0, label: "Opens each cited step or row", flag: "manual" }, { lane: 0, label: "Unproven causes back in the pile", flag: "error" }, { lane: 2, label: "Challenges and accepts", flag: "ok" }] }, caption: "Chains first, evidence second, in separate asks. You confirm every citation; anything the agent can’t point at goes back in the pile." },
        { t: "prompt", title: "Build the why-chains", text: "Here are my current flow trace and baseline measurements: [paste both].\nList the symptoms, each with its number and where it comes from (trace step or baseline row).\nFor each symptom, build a why-chain down to a system condition — data, integration, code, infrastructure or a manual step. Never stop at a person.\nNote any cause that sits inside a vendor system.\nDon’t claim evidence yet; just the chains.\n\nCheck in its answer: every symptom has a number you recognise; no chain ends at a person; chains that converge are pointed out." },
        { t: "prompt", title: "Evidence and challenge", text: "Here are my candidate causes: [paste].\nFor each cause, find the evidence in my trace, baseline or logs and quote the step, row or entry.\nMark any cause with no evidence as “unproven”.\nRank the evidenced causes by how much of the baseline they explain, and show how you estimated it.\nThen challenge the list: which causes are really symptoms in disguise?\n\nCheck in its answer: open each cited step or row and confirm it says what the agent claims; the ranking uses your numbers; you decide which unproven causes to dig into or drop." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask your agent to propose why-chains for each symptom, then ask it — separately — which trace steps or baseline numbers support each cause. Anything it can’t point at goes back in the pile." },

        { t: "h", text: "When it goes off the path" },
        { t: "table", caption: "Routes out of this lesson", head: ["Situation", "Route", "What you do"], rows: [
          ["Causes evidenced and ranked", "Forward", "Hand the root causes to 1.3.4 Write the Technical Problem Statement"],
          ["One obvious cause", "Alternate", "A short analysis is fine — but still check for contributors"],
          ["Causes without evidence", "Rework", "Back to the trace; dig again or mark unproven"],
          ["Evidence is mixed", "Exception", "Mark the confidence next to the cause"],
          ["Cause sits in a vendor system", "Edge case", "Record it as a constraint"],
          ["Cause in a system you can’t change", "Escalate", "Tech lead and the system’s owner"],
          ["Cause is non-technical (training, policy)", "Stop", "Hand it back to the client — recorded in the learning log"],
          ["No cause can be evidenced", "Failure", "The trace or baseline is too thin; go back and strengthen it"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [{ id: "q1", q: "Can any cause be evidenced?", yes: "q2", no: "fail" }, { id: "q2", q: "Does every cause have evidence?", yes: "q3", no: "rework" }, { id: "q3", q: "Is the cause technical?", yes: "q4", no: "stop" }, { id: "q4", q: "Can you change the system it sits in?", yes: "q6", no: "q5" }, { id: "q5", q: "Is it a vendor system?", yes: "constraint", no: "esc" }, { id: "q6", q: "Is the evidence mixed?", yes: "conf", no: "fwd" }, { id: "fail", result: "Failure: the trace or baseline is too thin — go back and strengthen it", tone: "bad" }, { id: "rework", result: "Rework: back to the trace; dig again or mark unproven", tone: "bad" }, { id: "stop", result: "Stop: hand it back to the client, recorded in the learning log", tone: "neutral" }, { id: "constraint", result: "Record it as a constraint", tone: "neutral" }, { id: "esc", result: "Escalate: tech lead and the system’s owner", tone: "neutral" }, { id: "conf", result: "Mark the confidence next to the cause", tone: "neutral" }, { id: "fwd", result: "Forward: hand the root causes to 1.3.4", tone: "good" }] }, caption: "The routes out of this lesson as questions. Causes you can’t change are not dropped: they become constraints or go to their owner." },
        { t: "figure", fig: { kind: "template", id: "technical-root-causes" }, caption: "The technical root-cause analysis — symptoms, why-chains, causes by category, their evidence and their ranking." },

        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "Stopping at the symptom: “orders are slow because there are lots of steps”.", fix: "Ask why again until a system or data condition appears." },
          { trap: "Blaming a person or a team.", fix: "Rewrite it as the condition that let it happen. Causes are stated without naming individuals." },
          { trap: "Keeping a cause because it feels right.", fix: "No evidence, no cause. Go back to the trace or mark it unproven." },
          { trap: "Naming a solution as a cause: “the cause is that we have no OCR”.", fix: "State the condition — orders arrive unstructured — and leave the fix for topic 1.4." },
          { trap: "Listing causes without ranking them.", fix: "Estimate each cause’s share of the baseline, so the statement can lead with what matters most." },
          { trap: "Dropping a cause because it’s in a vendor system you can’t touch.", fix: "Record it as a constraint. Solutions still have to live with it." },
        ] },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["Each cause cites trace or measurement evidence", "Causes, not people", "Causes in systems you can’t change are recorded as constraints"] },
        { t: "p", text: "Causes that surprised the team belong in the learning log. They’re often the most useful thing a project leaves behind for the next one." },
        { t: "try", text: "Run a why-chain on “3.1% of order lines are wrong”. Then do the same for your own project." },

        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Causes Evidenced", items: [
          "Every symptom comes from the trace or the baseline, with its number",
          "Every why-chain ends at a system condition, not a person",
          "Causes are sorted into data, integration, code, infrastructure or manual step",
          "Each cause (RC-##) cites its evidence and links to trace steps and baselines",
          "Causes are ranked by contribution and together explain most of the baseline",
          "Vendor-system causes are recorded as constraints; non-technical ones handed back",
          "The tech lead challenged and accepted the analysis",
        ] },
      ],
    },

    /* ───────────────────────────── 1.3.4 ───────────────────────────── */
    {
      id: "discover.problem.statement", fid: "discover.problem.statement", code: "1.3.4", title: "Write the Technical Problem Statement", minutes: 10,
      blocks: [
        { t: "lead", text: "Everything you’ve gathered comes together in one statement. A good technical problem statement makes the right solution feel obvious and lets the wrong ones rule themselves out." },
        { t: "tldr", items: [
          "Five clauses: what fails and where, how much, why, within which limits, and what a solution must achieve.",
          "Every clause links to evidence — a trace step, a baseline row, an RC or a C ID.",
          "No technology named: the statement judges options, it doesn’t pick one.",
          "A clause without evidence is removed or marked as an assumption.",
          "Accepted at the Technical Problem Review, it becomes the yardstick for topics 1.4 and 1.5.",
        ] },
        { t: "p", text: "The job: *help me state the problem so clearly that the right solution becomes obvious and the wrong ones rule themselves out.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "In the next topic you’ll research options. Every one of them will look good to someone. The problem statement is how you tell them apart: an option either gets order data into the system correctly without re-keying, within the constraints, at the target numbers — or it doesn’t. Without a statement, options are compared on enthusiasm." },
        { t: "figure", fig: { kind: "funnel", stages: [{ label: "Every option that looks good to someone" }, { label: "Gets order data in without re-keying" }, { label: "Within the constraints" }, { label: "At the target numbers" }, { label: "Options worth taking forward" }] }, caption: "The statement as a filter: each test an option has to pass. Without it, options are compared on enthusiasm." },
        { t: "p", text: "It also protects you from the most common Discover failure: a problem quietly redefined to fit a solution someone already likes. If the statement is written from evidence and names no technology, that move becomes visible." },
        { t: "pull", text: "Fall in love with the problem, not with the first solution you thought of." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "This is the last lesson of this topic and the end of the investigation. It takes three inputs — the **technical root-cause analysis**, the **baseline measurements** and the **technical constraint log** from topic 1.1 — and produces the **technical problem statement**, TPS-##. It hands that to **1.4 Research Solution Options**. Its decision is the topic’s gate: the **Technical Problem Review**." },
        { t: "figure", fig: { kind: "context", center: { label: "Write the Technical Problem Statement", sub: "1.3.4" }, around: [{ label: "Technical root-cause analysis", sub: "RC-##", type: "store", dir: "in" }, { label: "Baseline measurements", type: "store", dir: "in" }, { label: "Technical constraint log", sub: "C-## · topic 1.1", type: "store", dir: "in" }, { label: "Technical problem statement", sub: "TPS-##", type: "store", dir: "out" }, { label: "1.4 Research Solution Options", type: "system", dir: "out", link: "TPS-##" }, { label: "Tech lead", type: "person", dir: "both", link: "Technical Problem Review", text: "Runs the read-back and accepts the statement — the topic’s gate." }] }, caption: "Three inputs in, one statement out. The tech lead’s acceptance is the topic’s gate." },
        { t: "figure", fig: { kind: "trace", from: "REQ", to: "TPS" }, caption: "The statement sits on everything before it — and everything after it will be judged against it." },
        { t: "figure", fig: { kind: "workflow", fid: "discover.problem.statement" }, caption: "The lesson’s workflow: draft, link every clause to evidence, strip out solution words, then the tech lead’s read-back." },
        { t: "table", caption: "Who does what", head: ["Role", "RACI", "In this lesson"], rows: [
          ["Engineer", "Responsible", "Drafts the statement and links every clause"],
          ["Tech lead", "Accountable", "Runs the read-back and accepts the statement"],
          ["Architect", "Consulted", "Checks the statement could rule out a bad option"],
          ["Client contact", "Informed", "Told if the scope has changed since the brief"],
        ] },

        { t: "h", text: "Key ideas" },
        { t: "terms", items: [
          { term: "Technical problem statement (TPS)", def: "One statement of the problem in the system: what fails, where, how much, why, within which constraints, and what a solution must achieve." },
          { term: "Clause", def: "One part of the statement, carrying one claim — and one evidence link." },
          { term: "Evidence link", def: "The ID of what backs a clause: a trace step, a baseline row, an RC-## or a C-##." },
          { term: "Solution word", def: "Any word that names a technology or an approach — a tool, a product, a pattern. It belongs in topic 1.4, not here." },
          { term: "Assumption", def: "A clause you believe but can’t yet evidence. It may stay only if it’s marked as one." },
          { term: "Read-back", def: "The tech lead reads the statement aloud, clause by clause, and asks for the evidence behind each one." },
        ] },
        { t: "h3", text: "The five clauses" },
        { t: "table", caption: "What each clause says, and where its evidence comes from", head: ["Clause", "It says", "Evidence from"], rows: [
          ["What fails, where", "The failure in system terms", "Current flow trace (trace steps)"],
          ["How much", "The size of the problem today", "Baseline measurements"],
          ["Why", "The causes that produce it", "Root-cause analysis (RC-##)"],
          ["Within which limits", "The hard constraints any solution must respect", "Technical constraint log (C-##)"],
          ["A solution must", "The targets that define success — no technology", "Technical success metrics (M-##) and quality attributes"],
        ] },
        { t: "figure", fig: { kind: "tree", root: "Technical problem statement", children: [{ label: "What fails, where", children: [{ label: "Current flow trace", text: "Trace steps" }] }, { label: "How much", children: [{ label: "Baseline measurements" }] }, { label: "Why", children: [{ label: "Root-cause analysis", text: "RC-##" }] }, { label: "Within which limits", children: [{ label: "Technical constraint log", text: "C-##" }] }, { label: "A solution must", children: [{ label: "Success metrics and quality attributes", text: "M-##" }] }] }, caption: "The five clauses, each with the artifact its evidence comes from. Every earlier lesson feeds exactly one clause." },
        { t: "p", text: "This shape borrows from two standard places. The **problem statement canvas** forces the who, the problem, the impact and the evidence onto one page. **arc42**’s first section, introduction and goals, asks for the drivers and quality goals before any solution strategy. And **requirements traceability** — linking each claim to its source in both directions — is what turns a paragraph into something you can audit." },
        { t: "figure", fig: { kind: "knowledge", name: "Problem statement review" }, caption: "Problem statement review: a peer check, clause by clause — is it a problem, not a solution? Does each clause trace to evidence? Is it specific enough to test?" },

        { t: "h", text: "How to do it" },
        { t: "steps", items: [
          { title: "Draft the statement", text: "Write the five clauses from the template: what fails and where, how much (the baseline), why (the root causes), within which limits (the hard constraints), and what a solution must achieve (the targets from the success metrics). Write each as plain sentences in system terms. Lead with the causes that explain most of the baseline. Add evidence links as you draft, not afterwards — it’s much easier to notice an unsupported claim while you’re writing it.", tip: "If two separate problems emerge, write one statement each and rank them. Don’t blend them." },
          { title: "Link every clause to its evidence", text: "Next to each clause, write its evidence: trace step, baseline row, RC or C ID. Then build a small traceability table — clause on one side, evidence on the other — and look for empty cells. Any clause you can’t link is either redrafted, removed, or marked plainly as an assumption.", tip: "One clause, one claim. A clause with three claims in it needs three links, or it needs splitting." },
          { title: "Strip out solution words", text: "Read the statement for three kinds of word. Solution words — any tool, product or approach — come out; rewrite the clause as behaviour and numbers. Vague words — “slow”, “better”, “a lot” — become numbers from the baseline or the targets. Unsupported claims go back to step two. Carry security and data limits in from the constraint log; they’re part of the problem, not an afterthought.", tip: "A useful test: could a solution you dislike still satisfy this sentence? If the sentence quietly rules it out by naming its rival, a solution has crept in." },
          { title: "Decide: is the statement accepted?", text: "Prepare the statement for the tech lead’s read-back with the evidence links listed underneath. The tech lead reads it clause by clause and asks one question of the whole: could this statement rule out a bad option? An unsupported clause sends you back to redraft. If the scope has changed since the brief — bigger or smaller — the tech lead and the client are told. If there’s no problem worth solving technically, that’s a stop, recorded with its reasons." },
        ] },
        { t: "figure", fig: { kind: "tree", root: "Three kinds of word to strip", children: [{ label: "Solution words", text: "Any tool, product or approach — rewrite as behaviour and numbers." }, { label: "Vague words", text: "“Slow”, “better”, “a lot” — become numbers from the baseline or the targets." }, { label: "Unsupported claims", text: "Go back to step two and get linked." }] }, caption: "Step three, broken down. Security and data limits come in from the constraint log at the same time." },
        { t: "contrast", label: "A clause that smuggles in a solution", bad: { title: "Names a solution", text: "“We need an AI tool to read PDF orders and push them into the ERP.” It picks the answer, can’t be evidenced, and gives nothing to judge alternatives against." }, good: { title: "States the problem", text: "“Order data from e-mailed PDFs reaches the ERP only by manual re-keying (trace steps 2–3).” It names the failure, points at evidence, and leaves the solution open." } },
        { t: "contrast", label: "A target clause", bad: { title: "Vague", text: "“A solution must make order entry faster and more accurate.” Faster than what? How accurate is enough? Nothing can fail this test." }, good: { title: "Measurable", text: "“A solution must get ≥ 98% of lines into the ERP correctly without re-keying, lose no orders, and keep median time under 5 min at peak.”" } },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "A solution must " }, { text: "get ≥ 98% of lines into the ERP correctly without re-keying", label: "Accuracy target", note: "A number, not “more accurate”." }, { text: ", " }, { text: "lose no orders", label: "No losses" }, { text: ", and " }, { text: "keep median time under 5 min at peak", label: "Time target", note: "A number and a load, not “faster”." }, { text: "." }] }, caption: "The measurable target clause, part by part. Each part is something an option can fail." },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Northwind’s statement, TPS-01, uses every piece of evidence the topic produced — and names no technology." },
        { t: "table", caption: "TPS-01, clause by clause (from the technical problem statement example)", head: ["Clause", "TPS-01 says", "Evidence"], rows: [
          ["What fails, where", "Order data from e-mailed PDFs reaches the ERP only by manual re-keying.", "Trace steps 2–3"],
          ["How much", "Median 13 min per order (p95 24), 3.1% wrong lines, 0.4% orders missing — at ~80 orders a day, doubling at peak.", "Baseline measurements"],
          ["Why", "RC-1 orders are unstructured; RC-2 no path from inbox to the ERP import API; RC-3 customer codes not in any system.", "RC-1, RC-2, RC-3"],
          ["Within which limits", "C-01 import API only; C-02 data stays in the EU.", "C-01, C-02"],
          ["A solution must", "Get ≥ 98% of lines into the ERP correctly without re-keying, lose no orders, keep median time under 5 min at peak.", "M-1 to M-3; QA-1 to QA-3"],
        ] },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "Order data from e-mailed PDFs reaches the ERP only by manual re-keying. ", label: "What fails, where", note: "Trace steps 2–3" }, { text: "Median 13 min per order (p95 24), 3.1% wrong lines, 0.4% orders missing — at ~80 orders a day, doubling at peak. ", label: "How much", note: "Baseline measurements" }, { text: "RC-1 orders are unstructured; RC-2 no path from inbox to the ERP import API; RC-3 customer codes not in any system. ", label: "Why", note: "RC-1, RC-2, RC-3" }, { text: "C-01 import API only; C-02 data stays in the EU. ", label: "Within which limits", note: "C-01, C-02" }, { text: "A solution must get ≥ 98% of lines into the ERP correctly without re-keying, lose no orders, keep median time under 5 min at peak.", label: "A solution must", note: "M-1 to M-3; QA-1 to QA-3" }] }, caption: "TPS-01 read as one statement, with each clause’s evidence in its note. No technology appears anywhere in it." },
        { t: "callout", tone: "case", title: "Northwind", text: "TPS-01 traces every clause to the trace, the baseline and the constraints — and names no technology." },
        { t: "p", text: "Look at what it rules out without saying so. Any option that still has a person re-typing lines fails the first target. Any option that sends order data outside the EU fails C-02. Any option that writes to the ERP any other way than its import API fails C-01. And the “AI tool” from the request in topic 1.2 is nowhere in it: OCR, parsing services or anything else will have to *earn* their place in the next topic against these clauses. Note also what isn’t in it: A-01, the low-confidence guess about how many PDFs are scans, stays an assumption in the constraint log rather than becoming a clause." },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [{ id: "q1", q: "Does a person still re-type lines?", yes: "f1", no: "q2" }, { id: "q2", q: "Does order data leave the EU?", yes: "f2", no: "q3" }, { id: "q3", q: "Does it write to the ERP other than through its import API?", yes: "f3", no: "pass" }, { id: "f1", result: "Fails the first target", tone: "bad" }, { id: "f2", result: "Fails C-02", tone: "bad" }, { id: "f3", result: "Fails C-01", tone: "bad" }, { id: "pass", result: "Still in — it must earn its place against the clauses in the next topic", tone: "neutral" }] }, caption: "TPS-01 used on an option. It rules options out without naming any, and nothing passes just by being an “AI tool”." },
        { t: "figure", fig: { kind: "knowledge", name: "Traceability matrix" }, caption: "The traceability matrix: each clause of the statement against the evidence behind it, so an empty cell is impossible to miss." },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "Agents draft clean, confident prose — which is exactly the risk here. A well-written clause with no evidence behind it is more dangerous than a clumsy one, because nobody questions it. Use the agent to draft and to check traceability; then read the result as a sceptic." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Tech lead"], steps: [{ lane: 1, label: "Drafts the five clauses", sub: "no technology named" }, { lane: 1, label: "Tags each with an evidence ID", sub: "or UNSUPPORTED" }, { lane: 0, label: "Checks every ID and number", flag: "manual" }, { lane: 1, label: "Sceptic’s pass", sub: "solution words, vague words" }, { lane: 0, label: "Decides what goes forward" }, { lane: 2, label: "Read-back, clause by clause", flag: "ok" }] }, caption: "Drafting and checking with an agent. Clean prose is the risk here, so the deciding stays with you and the tech lead." },
        { t: "prompt", title: "Draft and link", text: "Here are my root-cause analysis, baseline measurements and technical constraint log: [paste all three].\nDraft the technical problem statement in five parts: what fails and where, how much (baseline), why (root causes), within which limits (hard constraints only), and what a solution must achieve (targets from the success metrics).\nName no technology, product or approach.\nAfter each clause, give its evidence ID — trace step, baseline row, RC or C — and mark any clause you can’t link as UNSUPPORTED.\nDon’t treat assumptions (A-##) as constraints.\n\nCheck in its answer: every ID it cites exists in what you pasted; every number matches your baseline exactly; no constraint is invented; UNSUPPORTED clauses are redrafted or removed." },
        { t: "prompt", title: "The sceptic’s pass", text: "Read this problem statement as a sceptical tech lead: [paste].\nFind solution words, vague words (“slow”, “better”, “easy”) and claims not backed by the evidence links underneath.\nFor each, propose a rewrite in terms of behaviour and numbers.\nThen tell me: which bad options would this statement rule out, and is there one it should rule out but doesn’t?\nPrepare the final version for read-back with the evidence links listed underneath.\n\nCheck in its answer: each rewrite still says what you meant; the options it says are ruled out really are; you, not the agent, decide what goes to the tech lead." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask your agent to draft the five clauses and tag each with its evidence ID. Then read it as a sceptic: is there a clause you couldn’t defend in a meeting? A solution hiding in a verb?" },

        { t: "h", text: "When it goes off the path" },
        { t: "callout", tone: "warn", title: "No evidence, no clause", text: "A clause without evidence is removed or marked as an assumption. And if the problem turns out smaller than the brief suggested, say so plainly — that’s a valuable finding." },
        { t: "table", caption: "Routes out of this lesson", head: ["Situation", "Route", "What you do"], rows: [
          ["Statement accepted", "Forward", "Hand TPS-## to 1.4 Research Solution Options"],
          ["Small problem", "Alternate", "A one-paragraph statement is enough"],
          ["Two separate problems", "Alternate", "One statement each, ranked"],
          ["A clause is unsupported", "Rework", "Redraft or remove it"],
          ["Problem smaller than the brief", "Edge case", "Say so plainly"],
          ["Problem bigger than the brief", "Exception", "Flag the scope to the tech lead"],
          ["Scope differs from the brief", "Escalate", "Tech lead and client"],
          ["No problem worth solving technically", "Stop", "Stop and record why — in the learning log"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [{ id: "q1", q: "Is there a problem worth solving technically?", yes: "q2", no: "stop" }, { id: "q2", q: "Is every clause supported?", yes: "q3", no: "rework" }, { id: "q3", q: "Are there two separate problems?", yes: "two", no: "q4" }, { id: "q4", q: "Is the problem bigger than the brief?", yes: "big", no: "q5" }, { id: "q5", q: "Is it smaller than the brief?", yes: "small", no: "fwd" }, { id: "stop", result: "Stop and record why, in the learning log", tone: "bad" }, { id: "rework", result: "Rework: redraft or remove the clause", tone: "bad" }, { id: "two", result: "One statement each, ranked", tone: "neutral" }, { id: "big", result: "Flag the scope to the tech lead; the client is told", tone: "neutral" }, { id: "small", result: "Say so plainly — it’s a valuable finding", tone: "neutral" }, { id: "fwd", result: "Forward: hand TPS-## to 1.4 Research Solution Options", tone: "good" }] }, caption: "The routes out of this lesson as questions. A problem that turns out smaller or bigger than the brief is reported, not reshaped to fit it." },
        { t: "p", text: "The statement is versioned when it changes. If the research in topic 1.4 turns up something that changes the problem — a cause you missed, a constraint that isn’t what you thought — you update the statement and its version, rather than letting options drift away from it." },
        { t: "figure", fig: { kind: "cycle", center: "The statement stays the yardstick", steps: [{ label: "Statement accepted", text: "TPS-## at its current version." }, { label: "Topic 1.4 research" }, { label: "Something changes the problem", text: "A cause you missed, or a constraint that isn’t what you thought." }, { label: "Update the statement and its version" }] }, caption: "The statement is versioned when it changes, so options are judged against the current problem instead of drifting away from it." },

        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "The statement names a solution.", fix: "Rewrite the clause in terms of behaviour and numbers. The statement must rule options in or out, not pick one." },
          { trap: "Clauses without evidence.", fix: "Remove them or mark them as assumptions. No evidence, no clause." },
          { trap: "Vague targets: “faster”, “more reliable”.", fix: "Use the numbers from the success metrics and the baseline." },
          { trap: "Promoting an assumption to a constraint because it’s convenient.", fix: "Only confirmed constraints go in “within which limits”. Assumptions stay in the log with their test." },
          { trap: "Inflating the problem to match the brief.", fix: "Report what the evidence shows. A smaller problem is a finding, not a failure." },
          { trap: "Blending two problems into one statement.", fix: "Write one statement each and rank them." },
        ] },
        { t: "figure", fig: { kind: "template", id: "technical-problem-statement" }, caption: "The technical problem statement — five clauses, each with its evidence, no technology named." },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["Every clause links to a trace, baseline or cause", "No solution is named", "The targets from the success metrics are included"] },
        { t: "p", text: "Keep one note for the learning log: **how far the problem moved from the brief**. Comparing the brief’s first description with the accepted statement is one of the clearest lessons Discover leaves behind." },
        { t: "try", text: "Write TPS-01 for the order-intake case in five clauses: what fails, how much, why, limits, a solution must…. Then do the same for your own project." },

        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Technical Problem Review", items: [
          "The trace is repeatable — another engineer has repeated it",
          "The baseline has a method, a sample and a period for every number",
          "Every cause cites trace or measurement evidence",
          "The statement has all five clauses: what fails, how much, why, limits, a solution must",
          "Every clause links to a trace step, baseline row, RC or C ID",
          "No solution, product or technology is named",
          "Targets from the success metrics are included as numbers",
          "The tech lead accepted the statement; the client was told if scope changed",
        ] },
      ],
    },
  ],
};
